    engine_name = os.getenv("P3_ENGINE", "rules")
    if engine_name not in {"rules", "deepseek"}:
        raise RuntimeError("P3_ENGINE must be rules or deepseek")
    engine = engine or (profile.make_engine(engine_name) if profile else (RuleEngine() if engine_name == "rules" else DeepSeekEngine()))
    catalog = catalog or RuleCatalog.load(os.getenv("P2_RULES_PATH"))
    manager_type = profile.manager_type if profile else Manager
    message_type = profile.message_type if profile else PlanningMessage
    clarification_type = profile.clarification_type if profile else ClarificationRequest
    result_type = profile.result_type if profile else AgentResult
    manager = manager_type(engine, reader, catalog, now=now, timeout_seconds=timeout_seconds)
    app = FastAPI(title=profile.title if profile else "Household V1-P3 read-only planning AI",
                  version=profile.version if profile else "0.4.0")

    def scope(authorization: str = Header(default=""), x_user_id: str = Header(default=""), x_household_id: str = Header(default="")):
        if not secrets.compare_digest(authorization.encode(), f"Bearer {token}".encode()) or not x_user_id.strip() or not x_household_id.strip():
            raise DomainError("UNAUTHENTICATED", "需要后端服务认证及可信用户、家庭上下文。", 401)
        return Scope(user_id=x_user_id, household_id=x_household_id)

    @app.exception_handler(DomainError)
    async def domain_error(request: Request, error: DomainError):
        return JSONResponse(status_code=error.status, content={"success": False, "data": None,
            "error": {"code": error.code, "message": error.message}, "trace_id": new_id("trace")})

    @app.exception_handler(RequestValidationError)
    async def validation(request: Request, error: RequestValidationError):
        return JSONResponse(status_code=422, content={"success": False, "data": None,
            "error": {"code": "VALIDATION_ERROR", "message": "请核对请求字段。", "fields": [
                {"location": list(e["loc"]), "type": e["type"]} for e in error.errors()]}, "trace_id": new_id("trace")})

    @app.exception_handler(TimeoutError)
    async def timeout(request: Request, error: TimeoutError):
        return JSONResponse(status_code=503, content={"success": False, "data": None,
            "error": {"code": "AGENT_TIMEOUT", "message": "读取或计算超时，请手动核对。"}, "trace_id": new_id("trace")})

    @app.get("/health")
    def health():
        body = {"status": "ok", "release_version": "V1-P3", "engine": engine_name,
            "policy_version": POLICY_VERSION, "ruleset_version": catalog.data.version, "ruleset_sha256": catalog.sha256,
            "clarification_protocols": ["p1", "p2-risk-selection-1", "p3-item-selection-1"],
            "planning_contract": "p3-planning-context-1", "inventory_writes": False,
            "shopping_writes": False, "production_chain_verified": False}
        if profile:
            body.update(profile.health)
        return body

    @app.post("/agent/message", response_model=result_type)
    async def message(body: message_type, identity: Scope = Depends(scope)):
        return await manager.handle(body, identity)

    @app.post("/agent/clarification", response_model=result_type)
    async def clarification(body: clarification_type, identity: Scope = Depends(scope)):
        return await manager.clarify(body, identity)

    @app.post("/consumption/query", response_model=result_type)
    async def consumption(body: Query, identity: Scope = Depends(scope)):
        return await manager.query(body, identity, "QUERY_CONSUMPTION")

    @app.post("/forecast/evaluate", response_model=result_type)
    async def forecast(body: Query, identity: Scope = Depends(scope)):
        return await manager.query(body, identity, "QUERY_FORECAST")

    @app.post("/procurement/suggest", response_model=result_type)
    async def procurement(body: Query, identity: Scope = Depends(scope)):
        return await manager.query(body, identity, "SUGGEST_PURCHASE")

    @app.post("/risk/evaluate", response_model=RiskResponse)
    async def risk(body: RiskQuery, identity: Scope = Depends(scope)):
        return await P2Manager(engine, reader, catalog, now=now, timeout_seconds=timeout_seconds).evaluate(body, identity)

    @app.get("/knowledge/rules")
    def rules(category: Category | None = None, identity: Scope = Depends(scope)):
        return {"ruleset_version": catalog.data.version, "ruleset_sha256": catalog.sha256,
                "rules": [r.model_dump(mode="json") for r in catalog.list_rules(category)]}

    if profile and hasattr(profile, "install_routes"):
        profile.install_routes(app, manager, scope)

    return app

import json
import re

from p0.deepseek import DeepSeekEngine as BaseDeepSeekEngine
from p0.engines import EngineError
from p2.engines import SYSTEM_PROMPT as P2_PROMPT, RuleEngine as P2RuleEngine
from .schemas import Parsed

PROMPT_VERSION = "p3-extract-2"
SYSTEM_PROMPT = P2_PROMPT.replace(
    "支持风险查询 QUERY_RISK；不支持耗尽预测、自动采购推荐、下单、拆批或语音音频。",
    "支持风险查询、消费统计、耗尽预测和补货建议；不支持下单、拆批或语音音频。"
).replace(
    "DISCARD, QUERY_RISK, UNSUPPORTED。",
    "DISCARD, QUERY_RISK, QUERY_CONSUMPTION, QUERY_FORECAST, SUGGEST_PURCHASE, UNSUPPORTED。"
).replace("缺字段为 null；", "未提供的名称、数量、单位、日期、位置为 null；") + """
V1-P3 扩展意图 QUERY_CONSUMPTION（已记录的消耗统计）、QUERY_FORECAST（未来能用多久/耗尽日期）、
SUGGEST_PURCHASE（应补什么/补货建议/依据库存生成补货草稿）。这些意图覆盖之前不支持预测推荐的限制。
仅提取 name、window_days（明确过去N天，1..28，默认28）、draft_mode（明确要求生成一项补货草稿时true）。
禁止生成速率、剩余日、建议数量、偏好、库存、事件、商品ID及事实。旧意图字段继续遵守原规则。
明确采购数量的“买2盒牛奶”仍为 PLAN_ADD；“给牛奶生成补货草稿”是 SUGGEST_PURCHASE。
多动作/多物品草稿设multiple_actions/multiple_items，查询全家统计或补货建议可以不指定name。
未知品名name=null；品名必须为原文连续片段。不要把问句或时间窗口当品名。超过28天查询不支持。
新增字段始终输出：window_days 必须是整数，未指定时为28，绝不能输出null；draft_mode必须是布尔值，默认为false，绝不能输出null。
示例：牛奶什么时候用完 -> {"intent":"QUERY_FORECAST","name":"牛奶","window_days":28,"draft_mode":false}
过去两周牛奶消耗统计 -> {"intent":"QUERY_CONSUMPTION","name":"牛奶","window_days":14,"draft_mode":false}
这个还能用多久 -> {"intent":"QUERY_FORECAST","name":null,"window_days":28,"draft_mode":false}
给牛奶生成补货草稿 -> {"intent":"SUGGEST_PURCHASE","name":"牛奶","window_days":28,"draft_mode":true}
"""


def parse_json_output(content):
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate JSON key")
            result[key] = value
        return result
    try:
        return Parsed.model_validate(json.loads(content, object_pairs_hook=unique))
    except (ValueError, TypeError):
        raise EngineError("INVALID_MODEL_OUTPUT") from None


class DeepSeekEngine(BaseDeepSeekEngine):
    def __init__(self, budget=None):
        super().__init__(budget, system_prompt=SYSTEM_PROMPT, output_parser=parse_json_output)


PATTERNS = {
    "SUGGEST_PURCHASE": r"补货建议|补货草稿|需要补什么|该补什么|应该买什么|建议补多少|建议买多少|需要补多少|生成.*补货|补货推荐",
    "QUERY_FORECAST": r"还能用多久|能用几天|还能喝几天|什么时候用完|何时用完|耗尽|几天用完|剩余天数|预计.*用完",
    "QUERY_CONSUMPTION": r"消耗统计|记录.*消耗|消耗了多少|用了多少|喝了多少|消费记录|消耗记录",
}


class RuleEngine:
    async def extract(self, text):
        matches = [intent for intent, pattern in PATTERNS.items() if re.search(pattern, text)]
        if not matches:
            return Parsed.model_validate((await P2RuleEngine().extract(text)).model_dump())
        if len(matches) > 1 or re.search(r"然后|并且|顺便|同时|再帮我", text):
            return Parsed(intent="UNSUPPORTED", multiple_actions=True)
        window = re.search(r"(?:过去|最近)(\d+)天", text)
        days = int(window[1]) if window else 14 if re.search(r"过去两周|最近两周", text) else 28
        if not 1 <= days <= 28:
            return Parsed(intent="UNSUPPORTED")
        intent = matches[0]
        value = re.sub(r"(?:过去|最近)\d+天|过去两周|最近两周|过去四周|最近四周", "", text)
        # Preserve only a literal span from the user's text as the item name.
        for pattern in (r"请|帮我|给|为|查询|查看|看看|生成|一份|一个|按记录|按现在记录的速度|按库存|家里|全家|所有物品|所有商品|记录的|记录了多少|记录了|预计|补货推荐",):
            value = re.sub(pattern, "", value)
        value = re.sub(r"补货建议|补货草稿|需要补什么|该补什么|应该买什么|建议补多少|建议买多少|需要补多少|还能用多久|能用几天|还能喝几天|什么时候用完|何时用完|耗尽日期|耗尽预测|耗尽|几天用完|剩余天数|消耗统计|消耗了多少|用了多少|喝了多少|消费记录|消耗记录|消耗|用完|这批|这个|这盒|[的了呢吗，。？?\s]", "", value)
        return Parsed(intent=intent, name=value or None, window_days=days,
                      draft_mode=bool(re.search(r"草稿", text)),
                      multiple_items=bool(re.search(r"以及|、|和", value)))

import json
import os
from urllib.request import ProxyHandler, Request, build_opener


def validate(body, engine):
    return (body.get("status") == "ok" and body.get("release_version") == "V1-P3"
        and body.get("engine") == engine and body.get("policy_version") == "p3-policy-1"
        and body.get("inventory_writes") is False and body.get("shopping_writes") is False
        and "p3-item-selection-1" in body.get("clarification_protocols", []))


def main():
    try:
        with build_opener(ProxyHandler({})).open(Request("http://127.0.0.1:8767/health"), timeout=3) as response:
